import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE_D 4
#define TILE_H 4
#define TILE_W 16
#define HALF_TILE_W (TILE_W / 2)
#define MAX_OC_PER_GROUP 32
__global__ void conv_transpose3d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int in_channels, int out_channels,
    int D_in, int H_in, int W_in,
    int D_out, int H_out, int W_out,
    int kD, int kH, int kW,
    int stride_d, int stride_h, int stride_w,
    int pad_d, int pad_h, int pad_w,
    int dil_d, int dil_h, int dil_w,
    int groups, int in_channels_per_group, int out_channels_per_group,
    bool has_bias,
    int tiles_h, int tiles_w,
    int size_d, int size_h, int size_w, int padded_w)
{
    extern __shared__ float smem[];
    int kElems = kD * kH * kW;
    int weight_size = out_channels_per_group * kElems;
    int padded_tile_vol = size_d * size_h * padded_w;
    float* s_weight[2];
    float* s_input[2];
    s_weight[0] = smem;
    s_weight[1] = smem + weight_size;
    s_input[0] = smem + 2 * weight_size;
    s_input[1] = s_input[0] + padded_tile_vol;
    int ng = blockIdx.y;
    int group = ng % groups;
    int n = ng / groups;
    int ic_start = group * in_channels_per_group;
    int oc_start = group * out_channels_per_group;
    int tile_idx = blockIdx.x;
    int tile_w_idx = tile_idx % tiles_w;
    int tmp_tile = tile_idx / tiles_w;
    int tile_h_idx = tmp_tile % tiles_h;
    int tile_d_idx = tmp_tile / tiles_h;
    int od0 = tile_d_idx * TILE_D;
    int oh0 = tile_h_idx * TILE_H;
    int ow0 = tile_w_idx * TILE_W;
    int t_d_min = od0 + pad_d - (kD - 1) * dil_d;
    int id_min = (t_d_min >= 0) ? (t_d_min / stride_d) : -(((-t_d_min) + stride_d - 1) / stride_d);
    int t_h_min = oh0 + pad_h - (kH - 1) * dil_h;
    int ih_min = (t_h_min >= 0) ? (t_h_min / stride_h) : -(((-t_h_min) + stride_h - 1) / stride_h);
    int t_w_min = ow0 + pad_w - (kW - 1) * dil_w;
    int iw_min = (t_w_min >= 0) ? (t_w_min / stride_w) : -(((-t_w_min) + stride_w - 1) / stride_w);
    int tid = threadIdx.x;
    int local_tw = tid % HALF_TILE_W;
    int tmp_l = tid / HALF_TILE_W;
    int local_th = tmp_l % TILE_H;
    int local_td = tmp_l / TILE_H;
    int od = od0 + local_td;
    int oh = oh0 + local_th;
    int ow_a = ow0 + local_tw;
    int ow_b = ow0 + local_tw + HALF_TILE_W;
    bool valid_out_a = (od < D_out) && (oh < H_out) && (ow_a < W_out);
    bool valid_out_b = (od < D_out) && (oh < H_out) && (ow_b < W_out);
    int tile_vol = size_d * size_h * size_w;
    float sum_a[MAX_OC_PER_GROUP];
    float sum_b[MAX_OC_PER_GROUP];
    #pragma unroll
    for (int i = 0; i < MAX_OC_PER_GROUP; i++) {
        sum_a[i] = 0.0f;
        sum_b[i] = 0.0f;
    }
    int valid_d[32];
    int ld_arr[32];
    for (int kd = 0; kd < kD; kd++) {
        int ok = 0, ld = 0;
        int t_d = od + pad_d - kd * dil_d;
        if (t_d % stride_d == 0) {
            int id = t_d / stride_d;
            if (id >= 0 && id < D_in) {
                ld = id - id_min;
                ok = 1;
            }
        }
        valid_d[kd] = ok;
        ld_arr[kd] = ld;
    }
    int valid_h[32];
    int lh_arr[32];
    for (int kh = 0; kh < kH; kh++) {
        int ok = 0, lh = 0;
        int t_h = oh + pad_h - kh * dil_h;
        if (t_h % stride_h == 0) {
            int ih = t_h / stride_h;
            if (ih >= 0 && ih < H_in) {
                lh = ih - ih_min;
                ok = 1;
            }
        }
        valid_h[kh] = ok;
        lh_arr[kh] = lh;
    }
    int valid_w_a[32];
    int lw_a_arr[32];
    int valid_w_b[32];
    int lw_b_arr[32];
    for (int kw = 0; kw < kW; kw++) {
        int ok_a = 0, lw_a = 0;
        if (valid_out_a) {
            int t_w_a = ow_a + pad_w - kw * dil_w;
            if (t_w_a % stride_w == 0) {
                int iw_a = t_w_a / stride_w;
                if (iw_a >= 0 && iw_a < W_in) {
                    lw_a = iw_a - iw_min;
                    ok_a = 1;
                }
            }
        }
        valid_w_a[kw] = ok_a;
        lw_a_arr[kw] = lw_a;
        int ok_b = 0, lw_b = 0;
        if (valid_out_b) {
            int t_w_b = ow_b + pad_w - kw * dil_w;
            if (t_w_b % stride_w == 0) {
                int iw_b = t_w_b / stride_w;
                if (iw_b >= 0 && iw_b < W_in) {
                    lw_b = iw_b - iw_min;
                    ok_b = 1;
                }
            }
        }
        valid_w_b[kw] = ok_b;
        lw_b_arr[kw] = lw_b;
    }
    // Prologue: load buffer 0 (ic_local = 0)
    {
        int ic0 = ic_start;
        for (int i = threadIdx.x; i < weight_size; i += blockDim.x) {
            int oc_local = i / kElems;
            int rem = i % kElems;
            long weight_idx = ((long)ic0 * out_channels_per_group + oc_local) * kElems + rem;
            s_weight[0][i] = weight[weight_idx];
        }
        for (int idx = threadIdx.x; idx < tile_vol; idx += blockDim.x) {
            int lw = idx % size_w;
            int tmp2 = idx / size_w;
            int lh = tmp2 % size_h;
            int ld = tmp2 / size_h;
            int id = id_min + ld;
            int ih = ih_min + lh;
            int iw = iw_min + lw;
            float val = 0.0f;
            if (id >= 0 && id < D_in && ih >= 0 && ih < H_in && iw >= 0 && iw < W_in) {
                long input_idx = (((long)n * in_channels + ic0) * D_in + id) * H_in * W_in + (long)ih * W_in + iw;
                val = input[input_idx];
            }
            int padded_idx = (ld * size_h + lh) * padded_w + lw;
            s_input[0][padded_idx] = val;
        }
    }
    __syncthreads();
    for (int ic_local = 0; ic_local < in_channels_per_group; ic_local++) {
        int cur = ic_local & 1;
        int nxt = cur ^ 1;
        bool has_next = (ic_local + 1 < in_channels_per_group);
        if (has_next) {
            int ic_next = ic_start + ic_local + 1;
            for (int i = threadIdx.x; i < weight_size; i += blockDim.x) {
                int oc_local = i / kElems;
                int rem = i % kElems;
                long weight_idx = ((long)ic_next * out_channels_per_group + oc_local) * kElems + rem;
                s_weight[nxt][i] = weight[weight_idx];
            }
            for (int idx = threadIdx.x; idx < tile_vol; idx += blockDim.x) {
                int lw = idx % size_w;
                int tmp2 = idx / size_w;
                int lh = tmp2 % size_h;
                int ld = tmp2 / size_h;
                int id = id_min + ld;
                int ih = ih_min + lh;
                int iw = iw_min + lw;
                float val = 0.0f;
                if (id >= 0 && id < D_in && ih >= 0 && ih < H_in && iw >= 0 && iw < W_in) {
                    long input_idx = (((long)n * in_channels + ic_next) * D_in + id) * H_in * W_in + (long)ih * W_in + iw;
                    val = input[input_idx];
                }
                int padded_idx = (ld * size_h + lh) * padded_w + lw;
                s_input[nxt][padded_idx] = val;
            }
        }
        if (valid_out_a || valid_out_b) {
            for (int kd = 0; kd < kD; kd++) {
                if (!valid_d[kd]) continue;
                int ld = ld_arr[kd];
                for (int kh = 0; kh < kH; kh++) {
                    if (!valid_h[kh]) continue;
                    int lh = lh_arr[kh];
                    int base_idx = ld * size_h + lh;
                    for (int kw = 0; kw < kW; kw++) {
                        bool wa = valid_w_a[kw];
                        bool wb = valid_w_b[kw];
                        if (!wa && !wb) continue;
                        float in_a = 0.0f, in_b = 0.0f;
                        if (wa) {
                            int s_idx_input_a = base_idx * padded_w + lw_a_arr[kw];
                            in_a = s_input[cur][s_idx_input_a];
                        }
                        if (wb) {
                            int s_idx_input_b = base_idx * padded_w + lw_b_arr[kw];
                            in_b = s_input[cur][s_idx_input_b];
                        }
                        int weight_base = kd * kH * kW + kh * kW + kw;
                        for (int oc_local = 0; oc_local < out_channels_per_group; oc_local++) {
                            float wv = s_weight[cur][oc_local * kElems + weight_base];
                            if (wa) sum_a[oc_local] += in_a * wv;
                            if (wb) sum_b[oc_local] += in_b * wv;
                        }
                    }
                }
            }
        }
        if (has_next) {
            __syncthreads();
        }
    }
    for (int oc_local = 0; oc_local < out_channels_per_group; oc_local++) {
        int oc = oc_start + oc_local;
        if (valid_out_a) {
            float out_a = sum_a[oc_local];
            if (has_bias) {
                out_a += bias[oc];
            }
            long output_idx_a = (((long)n * out_channels + oc) * D_out + od) * H_out * W_out + (long)oh * W_out + ow_a;
            output[output_idx_a] = out_a;
        }
        if (valid_out_b) {
            float out_b = sum_b[oc_local];
            if (has_bias) {
                out_b += bias[oc];
            }
            long output_idx_b = (((long)n * out_channels + oc) * D_out + od) * H_out * W_out + (long)oh * W_out + ow_b;
            output[output_idx_b] = out_b;
        }
    }
}
torch::Tensor conv_transpose3d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int64_t stride_d, int64_t stride_h, int64_t stride_w,
    int64_t pad_d, int64_t pad_h, int64_t pad_w,
    int64_t out_pad_d, int64_t out_pad_h, int64_t out_pad_w,
    int64_t dil_d, int64_t dil_h, int64_t dil_w,
    int64_t groups)
{
    input = input.contiguous();
    weight = weight.contiguous();
    int N = input.size(0);
    int in_channels = input.size(1);
    int D_in = input.size(2);
    int H_in = input.size(3);
    int W_in = input.size(4);
    int out_channels_per_group = weight.size(1);
    int out_channels = out_channels_per_group * groups;
    int kD = weight.size(2);
    int kH = weight.size(3);
    int kW = weight.size(4);
    int in_channels_per_group = in_channels / groups;
    int D_out = (D_in - 1) * stride_d - 2 * pad_d + dil_d * (kD - 1) + out_pad_d + 1;
    int H_out = (H_in - 1) * stride_h - 2 * pad_h + dil_h * (kH - 1) + out_pad_h + 1;
    int W_out = (W_in - 1) * stride_w - 2 * pad_w + dil_w * (kW - 1) + out_pad_w + 1;
    auto output = torch::empty({N, out_channels, D_out, H_out, W_out}, input.options());
    bool has_bias = bias.defined() && bias.numel() > 0;
    int stride_d_i = (int)stride_d, stride_h_i = (int)stride_h, stride_w_i = (int)stride_w;
    int pad_d_i = (int)pad_d, pad_h_i = (int)pad_h, pad_w_i = (int)pad_w;
    int dil_d_i = (int)dil_d, dil_h_i = (int)dil_h, dil_w_i = (int)dil_w;
    int tiles_d = (D_out + TILE_D - 1) / TILE_D;
    int tiles_h = (H_out + TILE_H - 1) / TILE_H;
    int tiles_w = (W_out + TILE_W - 1) / TILE_W;
    int diff_d = (TILE_D - 1) + (kD - 1) * dil_d_i;
    int size_d = (diff_d + stride_d_i - 1) / stride_d_i + 1;
    int diff_h = (TILE_H - 1) + (kH - 1) * dil_h_i;
    int size_h = (diff_h + stride_h_i - 1) / stride_h_i + 1;
    int diff_w = (TILE_W - 1) + (kW - 1) * dil_w_i;
    int size_w = (diff_w + stride_w_i - 1) / stride_w_i + 1;
    int padded_w = size_w + 1;
    int weight_size = out_channels_per_group * kD * kH * kW;
    int shared_tile_vol = size_d * size_h * padded_w;
    size_t shared_mem_bytes = (size_t)(2 * weight_size + 2 * shared_tile_vol) * sizeof(float);
    dim3 block(TILE_D * TILE_H * HALF_TILE_W, 1, 1);
    int num_tiles = tiles_d * tiles_h * tiles_w;
    dim3 grid(num_tiles, N * (int)groups, 1);
    const float* bias_ptr = nullptr;
    torch::Tensor bias_contig;
    if (has_bias) {
        bias_contig = bias.contiguous();
        bias_ptr = bias_contig.data_ptr<float>();
    }
    if (shared_mem_bytes > 48 * 1024) {
        cudaFuncSetAttribute(conv_transpose3d_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)shared_mem_bytes);
    }
    conv_transpose3d_kernel<<<grid, block, shared_mem_bytes>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        N, in_channels, out_channels,
        D_in, H_in, W_in,
        D_out, H_out, W_out,
        kD, kH, kW,
        stride_d_i, stride_h_i, stride_w_i,
        pad_d_i, pad_h_i, pad_w_i,
        dil_d_i, dil_h_i, dil_w_i,
        (int)groups, in_channels_per_group, out_channels_per_group,
        has_bias,
        tiles_h, tiles_w,
        size_d, size_h, size_w, padded_w
    );
    return output;
}
"""

cpp_source = """
torch::Tensor conv_transpose3d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int64_t stride_d, int64_t stride_h, int64_t stride_w,
    int64_t pad_d, int64_t pad_h, int64_t pad_w,
    int64_t out_pad_d, int64_t out_pad_h, int64_t out_pad_w,
    int64_t dil_d, int64_t dil_h, int64_t dil_w,
    int64_t groups);
"""

conv_transpose3d_ext = load_inline(
    name="conv_transpose3d_ext",
    cpp_sources=cpp_source,
    cuda_sources=source,
    functions=["conv_transpose3d_forward"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Performs a transposed 3D convolution operation using a custom CUDA kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, output_padding: int = 0,
                 dilation: int = 1, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.dilation = dilation
        self.groups = groups

        weight = torch.empty(in_channels, out_channels // groups, kernel_size, kernel_size, kernel_size)
        self.weight = nn.Parameter(weight)
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter('bias', None)

        self.reset_parameters()

    def reset_parameters(self):
        nn.init.kaiming_uniform_(self.weight, a=5 ** 0.5)
        if self.bias is not None:
            fan_in = self.in_channels
            bound = 1 / (fan_in ** 0.5)
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        bias = self.bias if self.bias is not None else torch.empty(0, device=x.device, dtype=x.dtype)
        return conv_transpose3d_ext.conv_transpose3d_forward(
            x, self.weight, bias,
            self.stride, self.stride, self.stride,
            self.padding, self.padding, self.padding,
            self.output_padding, self.output_padding, self.output_padding,
            self.dilation, self.dilation, self.dilation,
            self.groups
        )

