import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE_D 4
#define TILE_H 4
#define TILE_W 16
#define HALF_TILE_W (TILE_W / 2)
#define MAX_OC_PER_GROUP 32
__global__ void conv_transpose3d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int in_channels, int out_channels,
    int D_in, int H_in, int W_in,
    int D_out, int H_out, int W_out,
    int kD, int kH, int kW,
    int stride_d, int stride_h, int stride_w,
    int pad_d, int pad_h, int pad_w,
    int dil_d, int dil_h, int dil_w,
    int groups, int in_channels_per_group, int out_channels_per_group,
    bool has_bias,
    int tiles_h, int tiles_w,
    int size_d, int size_h, int size_w, int padded_w)
{
    extern __shared__ float smem[];
    int kElems = kD * kH * kW;
    int weight_size = out_channels_per_group * kElems;
    float* s_weight = smem;
    float* s_input = smem + weight_size;
    int ng = blockIdx.y;
    int group = ng % groups;
    int n = ng / groups;
    int ic_start = group * in_channels_per_group;
    int oc_start = group * out_channels_per_group;
    int tile_idx = blockIdx.x;
    int tile_w_idx = tile_idx % tiles_w;
    int tmp_tile = tile_idx / tiles_w;
    int tile_h_idx = tmp_tile % tiles_h;
    int tile_d_idx = tmp_tile / tiles_h;
    int od0 = tile_d_idx * TILE_D;
    int oh0 = tile_h_idx * TILE_H;
    int ow0 = tile_w_idx * TILE_W;
    int t_d_min = od0 + pad_d - (kD - 1) * dil_d;
    int id_min = (t_d_min >= 0) ? (t_d_min / stride_d) : -(((-t_d_min) + stride_d - 1) / stride_d);
    int t_h_min = oh0 + pad_h - (kH - 1) * dil_h;
    int ih_min = (t_h_min >= 0) ? (t_h_min / stride_h) : -(((-t_h_min) + stride_h - 1) / stride_h);
    int t_w_min = ow0 + pad_w - (kW - 1) * dil_w;
    int iw_min = (t_w_min >= 0) ? (t_w_min / stride_w) : -(((-t_w_min) + stride_w - 1) / stride_w);
    int tid = threadIdx.x;
    int local_tw = tid % HALF_TILE_W;
    int tmp_l = tid / HALF_TILE_W;
    int local_th = tmp_l % TILE_H;
    int local_td = tmp_l / TILE_H;
    int od = od0 + local_td;
    int oh = oh0 + local_th;
    int ow_a = ow0 + local_tw;
    int ow_b = ow0 + local_tw + HALF_TILE_W;
    bool valid_out_a = (od < D_out) && (oh < H_out) && (ow_a < W_out);
    bool valid_out_b = (od < D_out) && (oh < H_out) && (ow_b < W_out);
    int padded_tile_vol = size_d * size_h * padded_w;
    int tile_vol = size_d * size_h * size_w;
    float sum_a[MAX_OC_PER_GROUP];
    float sum_b[MAX_OC_PER_GROUP];
    #pragma unroll
    for (int i = 0; i < MAX_OC_PER_GROUP; i++) {
        sum_a[i] = 0.0f;
        sum_b[i] = 0.0f;
    }
    int valid_d[32];
    int ld_arr[32];
    for (int kd = 0; kd < kD; kd++) {
        int ok = 0, ld = 0;
        int t_d = od + pad_d - kd * dil_d;
        if (t_d % stride_d == 0) {
            int id = t_d / stride_d;
            if (id >= 0 && id < D_in) {
                ld = id - id_min;
                ok = 1;
            }
        }
        valid_d[kd] = ok;
        ld_arr[kd] = ld;
    }
    int valid_h[32];
    int lh_arr[32];
    for (int kh = 0; kh < kH; kh++) {
        int ok = 0, lh = 0;
        int t_h = oh + pad_h - kh * dil_h;
        if (t_h % stride_h == 0) {
            int ih = t_h / stride_h;
            if (ih >= 0 && ih < H_in) {
                lh = ih - ih_min;
                ok = 1;
            }
        }
        valid_h[kh] = ok;
        lh_arr[kh] = lh;
    }
    int valid_w_a[32];
    int lw_a_arr[32];
    int valid_w_b[32];
    int lw_b_arr[32];
    for (int kw = 0; kw < kW; kw++) {
        int ok_a = 0, lw_a = 0;
        if (valid_out_a) {
            int t_w_a = ow_a + pad_w - kw * dil_w;
            if (t_w_a % stride_w == 0) {
                int iw_a = t_w_a / stride_w;
                if (iw_a >= 0 && iw_a < W_in) {
                    lw_a = iw_a - iw_min;
                    ok_a = 1;
                }
            }
        }
        valid_w_a[kw] = ok_a;
        lw_a_arr[kw] = lw_a;
        int ok_b = 0, lw_b = 0;
        if (valid_out_b) {
            int t_w_b = ow_b + pad_w - kw * dil_w;
            if (t_w_b % stride_w == 0) {
                int iw_b = t_w_b / stride_w;
                if (iw_b >= 0 && iw_b < W_in) {
                    lw_b = iw_b - iw_min;
                    ok_b = 1;
                }
            }
